  Offset project(Vector3 position, Scene scene) {
    // Matriz de projeção da câmera
    Matrix4 projectionMatrix = scene.camera.projectionMatrix;

    // Matriz de visão da câmera
    Matrix4 viewMatrix = scene.camera.lookAtMatrix;

    // Matriz de transformação completa (projeção * visão)
    Matrix4 transformMatrix = projectionMatrix * viewMatrix;

    // Posição em espaço de câmera
    Vector4 posCameraSpace = transformMatrix
        .transform(Vector4(position.x, position.y, position.z, 1.0));

    // Normalização do ponto (perspective divide)
    if (posCameraSpace.w != 0.0) {
      posCameraSpace.x /= posCameraSpace.w;
      posCameraSpace.y /= posCameraSpace.w;
      posCameraSpace.z /= posCameraSpace.w;
    }

    // Coordenadas da tela
    double screenX =
        (posCameraSpace.x + 1.0) * 0.5 * scene.camera.viewportWidth;
    double screenY =
        (1.0 - posCameraSpace.y) * 0.5 * scene.camera.viewportHeight;

    return Offset(screenX, screenY);
