  Vector3 unproject2(Offset screenPosition, Scene scene, double depth) {
    double screenX = 2.0 * screenPosition.dx / scene.camera.viewportWidth - 1.0;
    double screenY =
        1.0 - 2.0 * screenPosition.dy / scene.camera.viewportHeight;

    Vector4 screenPos = Vector4(screenX, screenY, depth, 1.0);

    Matrix4 inverseProjectionMatrix =
        Matrix4.copy(scene.camera.projectionMatrix);
