    _balls[0].velocityX -= force * cos(angle);
    _balls[0].velocityY += force * sin(angle);
  }

  void _startAnimation() {
    _lastTime = DateTime.now().millisecondsSinceEpoch / 1000.0;
    _update();
  }

  void _update() {
    double currentTime = DateTime.now().millisecondsSinceEpoch / 1000.0;
    double dt = currentTime - _lastTime;
    _lastTime = currentTime;

    setState(() {
      for (var ballIndex = 0; ballIndex < _balls.length; ballIndex++) {
        _balls[ballIndex].update(dt, friction, _rectangles);

        projections[ballIndex] =
            project(_balls[ballIndex].ball.position, _scene);
      }
