    if (isLoaded) {
      // projection = project(_balls[0].ball.position, _scene);
    }

    WidgetsBinding.instance.scheduleFrameCallback((_) => _update());
  }

  void updateCue(Offset details, Offset ball) {
    // Posição da bola
    double ballX = ball.dx;
    double ballY = ball.dy;

    // Cálculo da diferença de coordenadas
    double dx = details.dx - ballX;
    double dy = details.dy - ballY;

    // Cálculo do ângulo
    double angle = atan2(dy, dx);

    // Criação da matriz de rotação
    Matrix4 rotationMatrix = Matrix4.rotationZ(angle);

    // Vetor de offset
    Vector3 offsetVector = Vector3(10, 0, 0); // Distância do taco à bola

    // Nova posição do taco
    Vector3 newPos = rotationMatrix.transform3(offsetVector);

    // Ajustar a posição do taco em relação à bola
    double cueX = ballX + newPos.x;
    double cueY = ballY + newPos.y;

    setState(() {
      cuePosition = Offset(cueX, cueY);
      cueAngle = angle; // Guardar o ângulo para a rotação do taco
    });
  }

  Offset project(Vector3 position, Scene scene) {
    // Matriz de projeção da câmera
    Matrix4 projectionMatrix = scene.camera.projectionMatrix;

    // Matriz de visão da câmera
    Matrix4 viewMatrix = scene.camera.lookAtMatrix;

    // Matriz de transformação completa (projeção * visão)
    Matrix4 transformMatrix = projectionMatrix * viewMatrix;

    // Posição em espaço de câmera
    Vector4 posCameraSpace = transformMatrix
        .transform(Vector4(position.x, position.y, position.z, 1.0));

    // Normalização do ponto (perspective divide)
    if (posCameraSpace.w != 0.0) {
      posCameraSpace.x /= posCameraSpace.w;
      posCameraSpace.y /= posCameraSpace.w;
      posCameraSpace.z /= posCameraSpace.w;
    }

    // Coordenadas da tela
    double screenX =
        (posCameraSpace.x + 1.0) * 0.5 * scene.camera.viewportWidth;
    double screenY =
        (1.0 - posCameraSpace.y) * 0.5 * scene.camera.viewportHeight;

    return Offset(screenX, screenY);
  }

  Vector3 unproject2(Offset screenPosition, Scene scene, double depth) {
    double screenX = 2.0 * screenPosition.dx / scene.camera.viewportWidth - 1.0;
    double screenY =
        1.0 - 2.0 * screenPosition.dy / scene.camera.viewportHeight;

    Vector4 screenPos = Vector4(screenX, screenY, depth, 1.0);

    Matrix4 inverseProjectionMatrix =
        Matrix4.copy(scene.camera.projectionMatrix);
    inverseProjectionMatrix.invert();

    Matrix4 inverseViewMatrix = Matrix4.copy(scene.camera.lookAtMatrix);
    inverseViewMatrix.invert();

    Vector4 viewPos = inverseProjectionMatrix.transform(screenPos);
    if (viewPos.w != 0.0) {
      viewPos.x /= viewPos.w;
      viewPos.y /= viewPos.w;
      viewPos.z /= viewPos.w;
    }

    Vector4 worldPos = inverseViewMatrix.transform(viewPos);
    return Vector3(worldPos.x, worldPos.y, worldPos.z);
  }

  Offset rectProj(Scene scene, Vector3 positions) {
    Offset position = Offset.zero;

    position = project(positions, scene);

    return position;
  }

